var e=JSON.parse(`[{"id":"med-osso-buco-risotto-milanese","name":"Osso buco et risotto milanese à la moelle","description":"Le duo milanais du dimanche : jarrets de veau braisés au vin blanc et gremolata, servis sur un risotto safrané monté à la moelle et au parmesan.","emoji":"🍖","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":35,"cookTime":120,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"veau-jarret","qty":4,"unit":"piece","note":"tranches de 4 cm, ficelées"},{"id":"os-a-moelle","qty":2,"unit":"piece","note":"moelle extraite, en dés"},{"id":"riz-rond","qty":240,"unit":"g","note":"carnaroli ou arborio"},{"id":"farine","qty":2,"unit":"cas"},{"id":"beurre","qty":45,"unit":"g"},{"id":"huile-olive","qty":1,"unit":"cas"},{"id":"oignon","qty":2,"unit":"piece","note":"finement ciselés"},{"id":"carotte","qty":2,"unit":"piece","note":"en petits dés"},{"id":"celeri-branche","qty":2,"unit":"piece","note":"en petits dés"},{"id":"vin-blanc","qty":300,"unit":"ml"},{"id":"tomates-concassees","qty":200,"unit":"g"},{"id":"bouillon-boeuf","qty":1400,"unit":"ml","note":"300 ml pour l’osso buco, le reste pour le risotto"},{"id":"safran","qty":2,"unit":"pincee"},{"id":"parmesan","qty":50,"unit":"g","note":"râpé"},{"id":"citron","qty":1,"unit":"piece","note":"zeste"},{"id":"persil","qty":15,"unit":"g"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Entaillez la peau des jarrets en 3 points pour qu’ils ne se recroquevillent pas, salez, puis farinez-les légèrement en tapotant l’excédent.","Dans une cocotte large, chauffez l’huile et 15 g de beurre à feu vif. Dorez les jarrets 4 min par face jusqu’à une croûte blonde. Réservez.","À feu moyen, faites suer un oignon, la carotte et le céleri 6 min. Déglacez avec 200 ml de vin blanc en grattant les sucs, laissez réduire de moitié (3 min), ajoutez les tomates et 300 ml de bouillon.","Remettez les jarrets à plat, couvrez et laissez frémir 1 h 45 à feu très doux, en les retournant à mi-cuisson. La viande doit se détacher de l’os à la fourchette.","40 min avant la fin, préparez la gremolata : hachez finement persil, ail et zeste de citron. Faites infuser le safran dans une louche de bouillon chaud et gardez le reste du bouillon frémissant.","Risotto : faites fondre la moelle et 15 g de beurre dans une sauteuse, faites suer le second oignon 4 min sans coloration, ajoutez le riz et nacrez-le 2 min. Déglacez avec 100 ml de vin blanc.","Ajoutez le bouillon louche par louche en remuant, en attendant qu’il soit absorbé à chaque fois, pendant 17-18 min. Versez le safran à mi-cuisson. Le grain doit rester légèrement ferme au cœur.","Hors du feu, mantecatura : incorporez 15 g de beurre froid et le parmesan, couvrez 2 min. Servez le risotto nappé, un jarret par assiette avec sa sauce et la gremolata parsemée au dernier moment."],"tags":["week-end","mijoté","abats","riche en collagène","réconfortant","calorique"],"seasons":["automne","hiver"],"technique":"braise","flavors":["umami","reconfortant","cremeux"],"tips":"Proposez une petite cuillère pour extraire la moelle des os du jarret : c’est le meilleur morceau. L’osso buco se réchauffe parfaitement le lendemain."},{"id":"med-risotto-cepes-foies-volaille","name":"Risotto aux cèpes et foies de volaille poêlés","description":"Un risotto crémeux aux champignons des bois, coiffé de foies de volaille saisis à la sauge et déglacés au vin blanc : terreux, fondant, très nourrissant.","emoji":"🍄","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":15,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"riz-rond","qty":180,"unit":"g","note":"carnaroli"},{"id":"champignon-forestier","qty":250,"unit":"g","note":"cèpes frais ou mélange forestier"},{"id":"foie-volaille","qty":280,"unit":"g","note":"parés, nerfs retirés"},{"id":"echalote","qty":2,"unit":"piece","note":"ciselées"},{"id":"vin-blanc","qty":120,"unit":"ml"},{"id":"bouillon-volaille","qty":800,"unit":"ml","note":"chaud"},{"id":"parmesan","qty":50,"unit":"g","note":"râpé"},{"id":"beurre","qty":40,"unit":"g"},{"id":"huile-olive","qty":1,"unit":"cas"},{"id":"sauge","qty":6,"unit":"feuille"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Nettoyez les cèpes au pinceau, coupez-les en lamelles de 5 mm. Faites-les sauter 5 min à feu vif dans l’huile d’olive jusqu’à ce qu’ils soient dorés et ne rendent plus d’eau. Salez et réservez.","Dans la même sauteuse, faites fondre 15 g de beurre à feu moyen, faites suer les échalotes 3 min. Ajoutez le riz et nacrez-le 2 min jusqu’à ce que les grains deviennent translucides sur les bords.","Versez 80 ml de vin blanc, laissez absorber, puis ajoutez le bouillon chaud louche par louche en remuant pendant 17 min. Remettez les deux tiers des cèpes à mi-cuisson.","Pendant ce temps, épongez les foies et salez-les. Dans une poêle très chaude, faites mousser 10 g de beurre avec la sauge, saisissez les foies 1 min 30 par face : ils doivent rester rosés à cœur. Déglacez avec le reste du vin, 30 secondes.","Hors du feu, incorporez au risotto le reste du beurre froid et le parmesan, couvrez 2 min : il doit napper et onduler quand on secoue l’assiette.","Dressez le risotto, posez les foies et leur jus par-dessus, le reste des cèpes, le persil haché et un tour de poivre."],"tags":["abats","riche en protéines","réconfortant","sans gluten","prise de masse"],"seasons":["automne"],"technique":"mijote","flavors":["umami","cremeux","reconfortant"],"tips":"Hors saison, réhydratez 30 g de cèpes séchés dans le bouillon chaud et complétez avec des champignons de Paris bruns."},{"id":"med-saltimbocca-tagliatelles-sauge","name":"Saltimbocca alla romana et tagliatelles au beurre","description":"Escalopes de veau fines coiffées de jambon cru et de sauge, saisies en deux minutes et déglacées au vin blanc, avec des tagliatelles fraîches enrobées du jus beurré.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":10,"cookTime":10,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"veau-escalope","qty":4,"unit":"piece","note":"fines, aplaties à 5 mm"},{"id":"jambon-cru","qty":4,"unit":"tranche","note":"prosciutto"},{"id":"sauge","qty":8,"unit":"feuille"},{"id":"farine","qty":1,"unit":"cas"},{"id":"beurre","qty":40,"unit":"g"},{"id":"vin-blanc","qty":80,"unit":"ml"},{"id":"pates-fraiches","qty":250,"unit":"g","note":"tagliatelles fraîches"},{"id":"parmesan","qty":30,"unit":"g","note":"râpé"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Portez une grande casserole d’eau salée à ébullition pour les pâtes.","Posez une tranche de jambon cru sur chaque escalope, puis 2 feuilles de sauge, et fixez avec un pique-olive. Farinez uniquement la face sans jambon.","Faites mousser 25 g de beurre dans une grande poêle à feu vif. Posez les escalopes côté jambon en premier 1 min, retournez et cuisez 1 min 30 : le veau doit rester rosé.","Plongez les tagliatelles dans l’eau bouillante pour 3 min. Pendant ce temps, retirez les escalopes sur une assiette chaude.","Déglacez la poêle avec le vin blanc en grattant les sucs, laissez réduire 1 min, ajoutez le reste du beurre et une louche d’eau de cuisson : la sauce doit devenir sirupeuse.","Égouttez les pâtes, faites-les sauter 30 secondes dans la sauce avec le parmesan. Servez avec les saltimbocca, un tour de poivre (peu de sel : le jambon sale déjà)."],"tags":["rapide","une poêle","riche en protéines","prise de masse","sportif"],"seasons":[],"technique":"poele","flavors":["herbace","umami"],"tips":"Remplacez le veau par de l’escalope de dinde pour une version économique ; le temps de cuisson est identique."},{"id":"med-spaghetti-carbonara","name":"Spaghetti alla carbonara (la vraie)","description":"Guanciale croustillant, jaunes d’œufs, pecorino et poivre noir concassé : la carbonara romaine sans crème, onctueuse grâce à l’eau des pâtes.","emoji":"🍝","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":10,"cookTime":12,"difficulty":"facile","servings":2,"ingredients":[{"id":"pates","qty":200,"unit":"g","note":"spaghetti ou rigatoni"},{"id":"pancetta","qty":120,"unit":"g","note":"guanciale idéalement, en bâtonnets de 1 cm"},{"id":"jaune-oeuf","qty":4,"unit":"piece"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"pecorino","qty":60,"unit":"g","note":"finement râpé"},{"id":"poivre","qty":1,"unit":"cac","note":"grains concassés"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Portez 3 l d’eau à ébullition et salez légèrement (le pecorino et le guanciale sont salés).","Dans un saladier, fouettez jaunes, œuf entier, pecorino et la moitié du poivre concassé jusqu’à obtenir une pâte épaisse.","Faites revenir le guanciale à sec dans une grande poêle froide mise sur feu moyen, 6-7 min, jusqu’à ce que le gras soit translucide et les bords croustillants. Coupez le feu.","Cuisez les pâtes 1 min de moins que le temps indiqué. Prélevez 200 ml d’eau de cuisson.","Versez les pâtes égouttées dans la poêle avec le guanciale et sa graisse, mélangez 30 secondes hors du feu pour qu’elles tiédissent légèrement.","Détendez la crème d’œufs avec 3 cuillères d’eau de cuisson, versez sur les pâtes et remuez vivement 1 min en ajoutant de l’eau par petites quantités : la sauce doit être nappante et brillante, sans grains d’œuf brouillé. Servez aussitôt avec le reste du poivre."],"tags":["rapide","une poêle","riche en protéines","calorique","réconfortant"],"seasons":[],"technique":"poele","flavors":["umami","cremeux"],"tips":"Si la sauce épaissit trop vite, posez le saladier quelques secondes sur la casserole d’eau chaude plutôt que sur le feu direct."},{"id":"med-ragu-bolognese-tagliatelle","name":"Ragù alla bolognese et tagliatelles fraîches","description":"Le vrai ragù de Bologne : bœuf et pancetta mijotés 3 heures au vin blanc et au lait, avec très peu de tomate, sur des tagliatelles aux œufs.","emoji":"🍝","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":25,"cookTime":180,"difficulty":"facile","servings":6,"ingredients":[{"id":"boeuf-hache","qty":750,"unit":"g","note":"paleron haché gros, 15 % MG"},{"id":"pancetta","qty":120,"unit":"g","note":"hachée au couteau"},{"id":"carotte","qty":2,"unit":"piece","note":"en brunoise"},{"id":"celeri-branche","qty":2,"unit":"piece","note":"en brunoise"},{"id":"oignon","qty":1,"unit":"piece","note":"en brunoise"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"beurre","qty":30,"unit":"g"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"tomates-concassees","qty":300,"unit":"g","note":"passata"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"lait","qty":200,"unit":"ml","note":"entier"},{"id":"bouillon-boeuf","qty":400,"unit":"ml"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"pates-fraiches","qty":600,"unit":"g","note":"tagliatelles aux œufs"},{"id":"parmesan","qty":60,"unit":"g","note":"râpé, au service"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une cocotte à fond épais, faites fondre la pancetta avec l’huile et le beurre à feu moyen 4 min. Ajoutez carotte, céleri et oignon et faites suer 10 min à feu doux, sans coloration.","Montez à feu vif, ajoutez le bœuf en l’écrasant à la cuillère et faites-le revenir 8-10 min jusqu’à ce que toute l’eau soit évaporée et que la viande grésille et brunisse légèrement.","Versez le vin blanc et laissez-le s’évaporer complètement (5 min) : l’odeur d’alcool doit disparaître.","Ajoutez passata, concentré, laurier, muscade et 200 ml de bouillon. Portez à frémissement puis réglez sur le feu le plus doux : une bulle toutes les deux secondes. Couvrez aux trois quarts.","Laissez mijoter 2 h 30 en remuant toutes les 30 min et en ajoutant un peu de bouillon si le fond attache. Versez le lait au bout de 2 h : il adoucit et lie la sauce.","Le ragù est prêt quand il est épais, brillant et que le gras perle en surface. Salez, poivrez, retirez le laurier.","Cuisez les tagliatelles 2-3 min à l’eau bouillante salée, égouttez en gardant une louche d’eau, et mélangez-les 1 min dans la sauteuse avec deux louches de ragù par portion. Servez avec le parmesan."],"tags":["batch cooking","week-end","mijoté","familial","préparation à l’avance","prise de masse"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["umami","reconfortant"],"tips":"Le ragù se garde 4 jours au frais et 3 mois au congélateur en portions : doublez les quantités, il ne demande pas plus de travail."},{"id":"med-spaghetti-vongole","name":"Spaghetti alle vongole","description":"Palourdes ouvertes au vin blanc, ail doré et piment, spaghetti finis dans le jus iodé et une pluie de persil : le plat de bord de mer napolitain en 20 minutes.","emoji":"🐚","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":10,"cookTime":15,"difficulty":"facile","servings":2,"ingredients":[{"id":"palourde","qty":800,"unit":"g","note":"dégorgées 1 h dans l’eau salée"},{"id":"pates","qty":200,"unit":"g","note":"spaghetti ou linguine"},{"id":"ail","qty":3,"unit":"gousse","note":"en fines lamelles"},{"id":"piment-frais","qty":1,"unit":"piece","note":"émincé, épépiné"},{"id":"vin-blanc","qty":100,"unit":"ml"},{"id":"huile-olive","qty":4,"unit":"cas"},{"id":"persil","qty":20,"unit":"g","note":"haché"},{"id":"beurre","qty":20,"unit":"g"},{"id":"citron","qty":1,"unit":"piece","note":"zeste","optional":true},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Rincez les palourdes et jetez celles qui restent ouvertes quand on les tapote. Portez l’eau des pâtes à ébullition, à peine salée.","Dans une grande sauteuse, chauffez 3 cuillères d’huile à feu moyen avec l’ail et le piment 2 min : l’ail doit être blond, pas brun.","Montez à feu vif, ajoutez les palourdes et le vin blanc, couvrez. Après 3-4 min, toutes les coquilles doivent être ouvertes. Retirez-les à l’écumoire et gardez le jus dans la sauteuse.","Cuisez les spaghetti 2 min de moins que le temps indiqué, égouttez-les et terminez la cuisson 2 min dans le jus des palourdes, à feu vif, en ajoutant un peu d’eau de cuisson si besoin.","Hors du feu, ajoutez le beurre, le reste de l’huile et le persil, et mélangez énergiquement : le jus doit devenir légèrement crémeux et enrober les pâtes.","Remettez les palourdes (décortiquez-en la moitié si vous le souhaitez), ajoutez le zeste de citron et servez immédiatement."],"tags":["rapide","une poêle","riche en glucides","léger"],"seasons":["printemps","ete"],"technique":"poele","flavors":["iode","herbace","piquant"],"tips":"Les palourdes donnent un jus très salé : salez à peine l’eau de cuisson des pâtes."},{"id":"med-polenta-salsiccia-sugo","name":"Polenta crémeuse et saucisses au sugo de fenouil","description":"Saucisses dorées puis mijotées dans une sauce tomate au vin rouge, fenouil et romarin, versées sur une polenta onctueuse au parmesan. Le réconfort du Frioul.","emoji":"🌭","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":10,"cookTime":35,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"saucisse-toulouse","qty":300,"unit":"g","note":"ou salsiccia italienne"},{"id":"polenta","qty":150,"unit":"g","note":"précuite ou traditionnelle"},{"id":"eau","qty":650,"unit":"ml"},{"id":"beurre","qty":15,"unit":"g"},{"id":"parmesan","qty":30,"unit":"g","note":"râpé"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece","note":"émincé"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"vin-rouge","qty":100,"unit":"ml"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"légèrement écrasées"},{"id":"romarin","qty":1,"unit":"brin"},{"id":"huile-olive","qty":1,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez les saucisses en tronçons de 4 cm. Dorez-les 5 min à feu moyen-vif dans l’huile, dans une sauteuse, jusqu’à ce qu’elles soient bien colorées. Réservez.","Dans la graisse rendue, faites fondre l’oignon 5 min, ajoutez l’ail, les graines de fenouil et le romarin 1 min. Déglacez au vin rouge et laissez réduire 2 min.","Ajoutez les tomates, remettez les saucisses, couvrez et laissez mijoter 20 min à feu doux : la sauce doit épaissir et napper la cuillère.","Pendant ce temps, portez l’eau salée à ébullition et versez la polenta en pluie en fouettant. Cuisez à feu doux en remuant (5 min pour la précuite, 30-40 min pour la traditionnelle), jusqu’à ce qu’elle se détache des parois.","Hors du feu, incorporez le beurre et le parmesan : la polenta doit être souple et brillante. Ajoutez un peu d’eau chaude si elle se fige.","Versez la polenta dans des assiettes creuses, creusez un puits et garnissez de saucisses et de sugo. Poivrez."],"tags":["économique","réconfortant","familial","sans gluten","calorique"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["reconfortant","umami","herbace"],"tips":"Le reste de polenta, refroidi en plaque, se coupe en tranches à griller le lendemain."},{"id":"med-gnocchi-ragu-canard","name":"Gnocchi maison au ragù de canard","description":"Cuisses de canard effilochées après 2 heures de mijotage au vin rouge et romarin, sur des gnocchi de pomme de terre faits maison, légers comme des nuages.","emoji":"🦆","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":50,"cookTime":130,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"canard-cuisse","qty":3,"unit":"piece"},{"id":"pomme-de-terre-farineuse","qty":1000,"unit":"g","note":"bintje, de taille égale"},{"id":"farine","qty":230,"unit":"g","note":"+ pour le plan de travail"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece","note":"en brunoise"},{"id":"carotte","qty":1,"unit":"piece","note":"en brunoise"},{"id":"celeri-branche","qty":1,"unit":"piece","note":"en brunoise"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"vin-rouge","qty":250,"unit":"ml"},{"id":"tomates-concassees","qty":250,"unit":"g"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"romarin","qty":2,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"cannelle","qty":1,"unit":"pincee"},{"id":"parmesan","qty":30,"unit":"g","note":"râpé"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Piquez la peau des cuisses et faites-les dorer côté peau 10 min à feu moyen dans une cocotte à sec, puis 3 min côté chair. Retirez-les et videz la graisse en n’en gardant que 2 cuillères.","Faites suer oignon, carotte et céleri 8 min dans la graisse de canard, ajoutez l’ail 1 min. Déglacez au vin rouge et faites réduire de moitié (5 min).","Ajoutez tomates, bouillon, romarin, laurier et cannelle, remettez les cuisses, couvrez et laissez frémir 1 h 45 à feu très doux. La chair doit se détacher seule de l’os.","Pendant ce temps, cuisez les pommes de terre entières avec la peau 30-35 min à l’eau salée (la lame d’un couteau doit s’enfoncer sans résistance). Pelez-les chaudes et passez-les au presse-purée sur le plan de travail.","Laissez tiédir 5 min, ajoutez l’œuf, une pincée de sel et la farine en 3 fois en travaillant du bout des doigts, juste jusqu’à obtenir une pâte souple qui ne colle plus. Ne pétrissez pas : plus on travaille, plus les gnocchi durcissent.","Roulez la pâte en boudins de 2 cm, coupez des tronçons de 2 cm et passez-les sur le dos d’une fourchette. Posez-les sur un torchon fariné.","Effilochez la viande sans peau ni os, remettez-la dans la sauce et laissez réduire 10 min à découvert. Plongez les gnocchi par fournées dans l’eau bouillante salée : ils sont cuits 1 min après être remontés à la surface.","Récupérez les gnocchi à l’écumoire directement dans le ragù, mélangez délicatement 1 min et servez avec le parmesan."],"tags":["week-end","mijoté","réconfortant","calorique","prise de masse"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["umami","reconfortant"],"tips":"Les gnocchi crus se congèlent à plat sur une plaque, puis en sac : cuisez-les directement surgelés (2 min de plus). Gardez la graisse de canard pour rôtir des pommes de terre."},{"id":"med-tacchino-tonnato","name":"Dinde tonnato et pommes de terre tièdes","description":"La version piémontaise du vitello tonnato avec un rôti de dinde poché au vin blanc, tranché fin et nappé d’une sauce mayonnaise au thon, anchois et câpres.","emoji":"🦃","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":25,"cookTime":45,"restTime":180,"difficulty":"facile","servings":4,"ingredients":[{"id":"dinde-escalope","qty":800,"unit":"g","note":"filet de dinde entier, ficelé en rôti"},{"id":"vin-blanc","qty":300,"unit":"ml"},{"id":"eau","qty":700,"unit":"ml"},{"id":"carotte","qty":1,"unit":"piece"},{"id":"celeri-branche","qty":1,"unit":"piece"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thon-conserve","qty":160,"unit":"g","note":"à l’huile d’olive, égoutté"},{"id":"anchois","qty":4,"unit":"piece"},{"id":"capres","qty":2,"unit":"cas"},{"id":"jaune-oeuf","qty":2,"unit":"piece"},{"id":"huile-olive","qty":120,"unit":"ml","note":"douce"},{"id":"citron","qty":1,"unit":"piece","note":"jus"},{"id":"pomme-de-terre","qty":800,"unit":"g","note":"chair ferme"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Portez à frémissement l’eau, le vin blanc, la carotte, le céleri, le laurier et une cuillère de sel. Plongez le rôti : le liquide doit le couvrir. Pochez 35-40 min à petits frémissements, jusqu’à 70 °C à cœur.","Laissez refroidir le rôti dans son bouillon au moins 1 h, puis enveloppez-le et mettez-le 2 h au frais : il se tranchera bien plus finement.","Sauce : mixez les jaunes, le thon, les anchois, 1 cuillère de câpres et le jus de citron. Ajoutez l’huile en mince filet en mixant jusqu’à une mayonnaise épaisse, puis détendez avec 3-4 cuillères de bouillon de pochage : elle doit napper comme une crème.","Cuisez les pommes de terre en robe des champs 20-25 min à l’eau salée, pelez-les tièdes et coupez-les en rondelles épaisses.","Tranchez la dinde très finement (3 mm), disposez les tranches en rosace sur un plat et nappez entièrement de sauce.","Parsemez du reste de câpres et de persil, accompagnez des pommes de terre tièdes arrosées d’un filet d’huile et poivrées."],"tags":["repas froid","préparation à l’avance","lunch box","riche en protéines","sans gluten"],"seasons":["printemps","ete"],"technique":"poche","flavors":["umami","iode","cremeux"],"tips":"Avec du veau (noix ou quasi), c’est le vitello tonnato d’origine. Se garde 3 jours au frais, la sauce protège la viande."},{"id":"med-pollo-cacciatora","name":"Pollo alla cacciatora et pommes de terre au four","description":"Cuisses de poulet braisées « à la chasseur » avec tomates, olives noires, romarin et vin rouge, et des pommes de terre rôties qui cuisent en même temps.","emoji":"🍗","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":20,"cookTime":60,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":4,"unit":"piece","note":"coupées en 2 à l’articulation"},{"id":"pomme-de-terre","qty":1000,"unit":"g","note":"en quartiers"},{"id":"huile-olive","qty":5,"unit":"cas"},{"id":"oignon","qty":1,"unit":"piece","note":"émincé"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"poivron-rouge","qty":1,"unit":"piece","note":"en lanières"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"vin-rouge","qty":150,"unit":"ml"},{"id":"olive","qty":80,"unit":"g","note":"noires, type Gaeta"},{"id":"romarin","qty":3,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 210 °C. Mélangez les pommes de terre avec 3 cuillères d’huile, un brin de romarin effeuillé et du sel sur une plaque. Enfournez 45 min en les retournant une fois : elles doivent être dorées et croustillantes.","Salez les morceaux de poulet. Dans une cocotte, chauffez le reste d’huile à feu moyen-vif et dorez-les côté peau 6-7 min jusqu’à une peau bien brune, puis 2 min de l’autre côté. Réservez.","Retirez l’excédent de graisse, faites revenir l’oignon et le poivron 5 min, ajoutez l’ail écrasé et le romarin restant 1 min.","Déglacez au vin rouge et laissez réduire 3 min. Ajoutez les tomates, remettez le poulet peau vers le haut sans immerger la peau.","Couvrez et laissez mijoter 30 min à feu doux, puis ajoutez les olives et poursuivez 10 min à découvert pour réduire la sauce. Le jus doit être clair quand on pique la cuisse près de l’os.","Servez le poulet et sa sauce avec les pommes de terre rôties."],"tags":["familial","mijoté","batch cooking","sans gluten","réconfortant"],"seasons":["automne"],"technique":"braise","flavors":["herbace","umami","reconfortant"],"tips":"Encore meilleur réchauffé le lendemain ; la sauce restante est parfaite sur des pâtes."},{"id":"med-involtini-siciliani-pure","name":"Involtini de bœuf à la sicilienne, purée à l’huile d’olive","description":"Fines tranches de bœuf roulées autour d’une farce pecorino, pignons et raisins secs, mijotées dans une sauce tomate, avec une purée de pommes de terre à l’huile d’olive.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":25,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"boeuf-steak","qty":360,"unit":"g","note":"4 tranches très fines de tende de tranche, aplaties"},{"id":"pecorino","qty":30,"unit":"g","note":"râpé"},{"id":"pignons","qty":20,"unit":"g"},{"id":"raisins-secs","qty":20,"unit":"g"},{"id":"panure","qty":25,"unit":"g","note":"pain rassis mixé"},{"id":"persil","qty":10,"unit":"g","note":"haché"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"oignon","qty":1,"unit":"piece","note":"ciselé"},{"id":"vin-rouge","qty":80,"unit":"ml"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"pomme-de-terre-farineuse","qty":420,"unit":"g"},{"id":"lait","qty":100,"unit":"ml","note":"chaud"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Farce : faites dorer la chapelure 2 min dans 1 cuillère d’huile, mélangez-la avec pecorino, pignons, raisins secs, persil et une gousse d’ail hachée.","Étalez les tranches de bœuf, salez légèrement, répartissez la farce en laissant 1 cm de bord, roulez serré en rentrant les côtés et fermez avec un pique en bois.","Dans une sauteuse, dorez les involtini 4 min dans 1 cuillère d’huile à feu vif en les tournant sur toutes les faces. Réservez.","Faites suer l’oignon 4 min, ajoutez l’ail restant, déglacez au vin rouge 2 min, ajoutez les tomates et le laurier. Remettez les involtini, couvrez et laissez mijoter 30 min à feu doux en les retournant à mi-cuisson.","Pendant ce temps, cuisez les pommes de terre pelées et coupées en morceaux 20 min à l’eau salée. Écrasez-les au presse-purée avec le lait chaud et 1 cuillère d’huile d’olive, salez et poivrez.","Retirez les piques et servez les involtini nappés de sauce sur la purée."],"tags":["familial","réconfortant","riche en protéines","préparation à l’avance"],"seasons":[],"technique":"braise","flavors":["umami","sucre","reconfortant"],"tips":"Préparez une double dose : les involtini se congèlent dans leur sauce."},{"id":"med-porchetta-fenouil-pommes","name":"Porchetta maison, fenouil et pommes de terre rôtis","description":"Poitrine de porc roulée autour d’un filet mignon, parfumée à l’ail, au romarin et aux graines de fenouil, rôtie lentement jusqu’à une couenne craquante.","emoji":"🐖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":30,"cookTime":180,"restTime":720,"difficulty":"intermediaire","servings":6,"ingredients":[{"id":"porc-poitrine","qty":800,"unit":"g","note":"une plaque avec couenne, sans os"},{"id":"porc-filet-mignon","qty":600,"unit":"g"},{"id":"ail","qty":6,"unit":"gousse"},{"id":"romarin","qty":3,"unit":"brin"},{"id":"sauge","qty":8,"unit":"feuille"},{"id":"graines-fenouil","qty":2,"unit":"cac"},{"id":"citron","qty":1,"unit":"piece","note":"zeste"},{"id":"fenouil","qty":2,"unit":"piece","note":"en quartiers"},{"id":"pomme-de-terre","qty":1200,"unit":"g","note":"en gros morceaux"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["La veille : pilez l’ail, le romarin, la sauge, les graines de fenouil, le zeste et 2 cuillères à café de sel en pâte. Côté chair, quadrillez la poitrine en entailles de 5 mm et frottez-la avec la pâte.","Posez le filet mignon au centre, roulez la poitrine autour (couenne à l’extérieur) et ficelez serré tous les 3 cm. Salez la couenne et laissez une nuit au réfrigérateur, à découvert, pour qu’elle sèche.","Sortez la porchetta 1 h avant. Préchauffez le four à 160 °C. Posez-la sur une grille au-dessus d’un plat contenant le vin blanc et rôtissez 2 h 15, jusqu’à 68 °C à cœur.","Mélangez pommes de terre et fenouil avec l’huile et du sel. Ajoutez-les dans le plat sous la porchetta pour les 1 h 15 dernières minutes, en les retournant une fois.","Montez le four à 240 °C pour 20-25 min : la couenne doit gonfler, cloquer et devenir dorée et craquante. Surveillez pour qu’elle ne noircisse pas.","Laissez reposer 15 min sous une feuille de papier aluminium lâche, retirez la ficelle et tranchez en rondelles de 1,5 cm. Servez avec les légumes et le jus du plat."],"tags":["week-end","four","familial","préparation à l’avance","calorique","sans gluten"],"seasons":["automne","hiver"],"technique":"roti","flavors":["herbace","grille","umami"],"tips":"Les restes froids en tranches fines dans du pain au levain avec de la roquette font les meilleurs sandwichs de la semaine."},{"id":"med-fegato-veneziana-polenta","name":"Fegato alla veneziana et polenta grillée","description":"Foie de veau en fines lanières saisies minute sur un lit d’oignons fondus au beurre pendant 25 minutes, relevé d’un trait de vinaigre, avec des tranches de polenta grillées.","emoji":"🧅","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":10,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"foie-veau","qty":350,"unit":"g","note":"en lanières de 1 cm"},{"id":"oignon","qty":4,"unit":"piece","note":"doux, émincés très finement"},{"id":"beurre","qty":35,"unit":"g"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"vinaigre-cidre","qty":1,"unit":"cas","note":"vinaigre de vin blanc"},{"id":"sauge","qty":4,"unit":"feuille"},{"id":"persil","qty":10,"unit":"g","note":"haché"},{"id":"polenta","qty":150,"unit":"g","note":"précuite"},{"id":"eau","qty":600,"unit":"ml"},{"id":"parmesan","qty":30,"unit":"g","note":"râpé"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Polenta : versez-la en pluie dans l’eau bouillante salée en fouettant, cuisez 5 min, ajoutez le parmesan et étalez-la sur 2 cm d’épaisseur dans un plat huilé. Laissez prendre 15 min.","Pendant ce temps, faites fondre 20 g de beurre et 1 cuillère d’huile dans une grande poêle, ajoutez les oignons et une pincée de sel. Couvrez et laissez fondre 20 min à feu doux en remuant de temps en temps : ils doivent être translucides, très tendres et à peine blonds.","Découvrez, déglacez avec le vinaigre et laissez évaporer 1 min. Réservez les oignons dans un bol.","Coupez la polenta en tranches et faites-les dorer 3 min par face dans une poêle-gril huilée et bien chaude.","Dans la poêle des oignons, faites mousser le reste du beurre avec la sauge à feu vif. Saisissez le foie en une seule couche 1 min en remuant : l’extérieur doit être gris-brun et l’intérieur rosé.","Remettez les oignons, mélangez 30 secondes, salez, poivrez, parsemez de persil et servez aussitôt avec la polenta grillée."],"tags":["abats","riche en protéines","sans gluten","économique","une poêle"],"seasons":[],"technique":"poele","flavors":["umami","sucre","acidule"],"tips":"Ne salez le foie qu’en fin de cuisson et ne le cuisez jamais plus de 2 min : il deviendrait granuleux."},{"id":"med-panzanella-poulet-grille","name":"Panzanella toscane au poulet grillé","description":"Pain au levain rassis imbibé de jus de tomates, concombre, oignon rouge, câpres et basilic, avec du poulet grillé tranché et de la mozzarella : un vrai repas d’été froid.","emoji":"🥗","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"italienne","prepTime":15,"cookTime":12,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"poulet-blanc","qty":2,"unit":"piece"},{"id":"pain-levain","qty":180,"unit":"g","note":"rassis d’un ou deux jours"},{"id":"tomate","qty":4,"unit":"piece","note":"bien mûres"},{"id":"concombre","qty":0.5,"unit":"piece"},{"id":"oignon-rouge","qty":0.5,"unit":"piece","note":"en fines lamelles"},{"id":"mozzarella","qty":1,"unit":"piece"},{"id":"capres","qty":1,"unit":"cas"},{"id":"basilic","qty":15,"unit":"g"},{"id":"huile-olive","qty":5,"unit":"cas"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"vinaigre de vin rouge"},{"id":"origan","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Couvrez l’oignon rouge d’eau froide avec 1 cuillère de vinaigre pendant 10 min pour l’adoucir.","Coupez les tomates en gros morceaux au-dessus d’un saladier, salez-les et laissez-les rendre leur jus 10 min.","Aplatissez les blancs de poulet à 2 cm d’épaisseur, frottez-les d’1 cuillère d’huile, d’origan et de sel. Grillez-les 5-6 min par face sur une poêle-gril très chaude, jusqu’à 72 °C à cœur. Laissez reposer 5 min et tranchez.","Coupez le pain en cubes de 3 cm, faites-les dorer 3 min à sec dans la poêle, puis versez-les dans le saladier avec les tomates et leur jus.","Ajoutez concombre en demi-rondelles, oignon égoutté, câpres, mozzarella déchirée, basilic, le reste de l’huile et du vinaigre. Mélangez et laissez le pain s’imbiber 10 min.","Répartissez dans les assiettes et posez le poulet tranché par-dessus. Poivrez généreusement."],"tags":["rapide","repas froid","lunch box","riche en protéines","économique"],"seasons":["ete"],"technique":"grill","flavors":["frais","acidule","herbace"],"tips":"Pour la lunch box, gardez le pain à part et mélangez au moment de manger."},{"id":"med-insalata-orzo-bresaola","name":"Salade d’orge perlé, bresaola, roquette et parmesan","description":"Orge perlé al dente au citron, tomates cerises, roquette poivrée, pignons grillés et copeaux de parmesan, avec de fines tranches de bresaola : la lunch box lombarde.","emoji":"🥗","category":"salade-composee","mealTypes":["dejeuner"],"cuisine":"italienne","prepTime":10,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"orge","qty":160,"unit":"g","note":"perlé, rincé"},{"id":"boeuf-seche","qty":120,"unit":"g","note":"bresaola en tranches fines"},{"id":"roquette","qty":60,"unit":"g"},{"id":"tomate-cerise","qty":150,"unit":"g","note":"coupées en deux"},{"id":"parmesan","qty":50,"unit":"g","note":"en copeaux"},{"id":"pignons","qty":20,"unit":"g"},{"id":"citron","qty":1,"unit":"piece","note":"zeste et jus"},{"id":"huile-olive","qty":4,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez l’orge 25 min à l’eau bouillante salée : il doit être tendre mais garder une petite résistance sous la dent. Égouttez et rincez à l’eau froide.","Pendant la cuisson, faites dorer les pignons 3 min à sec dans une poêle à feu moyen en remuant, jusqu’à ce qu’ils soient blonds et parfumés.","Fouettez le jus et le zeste de citron avec l’huile, du sel et du poivre.","Mélangez l’orge tiède avec la moitié de la vinaigrette et les tomates cerises : le grain absorbe mieux l’assaisonnement en tiédissant.","Au moment de servir, ajoutez la roquette, le reste de vinaigrette, et dressez avec la bresaola en pétales, les copeaux de parmesan et les pignons."],"tags":["lunch box","repas froid","préparation à l’avance","riche en protéines"],"seasons":["printemps","ete"],"technique":"bouilli","flavors":["frais","acidule","umami"],"tips":"L’orge assaisonné se garde 3 jours au frais : ajoutez roquette et bresaola au dernier moment."},{"id":"med-souvlaki-porc-pita-tzatziki","name":"Souvlaki de porc, pita grillée et tzatziki","description":"Brochettes d’échine de porc marinées au citron, origan et ail, grillées au feu vif, dans des pitas chaudes avec tomates, oignon rouge et un tzatziki bien épais.","emoji":"🍢","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":25,"cookTime":15,"restTime":120,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"porc-echine","qty":340,"unit":"g","note":"en cubes de 3 cm"},{"id":"citron","qty":1,"unit":"piece"},{"id":"origan","qty":2,"unit":"cac","note":"séché"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"pain-pita","qty":3,"unit":"piece"},{"id":"yaourt-grec","qty":200,"unit":"g","note":"entier"},{"id":"concombre","qty":0.5,"unit":"piece"},{"id":"aneth","qty":5,"unit":"g","note":"ou menthe"},{"id":"tomate","qty":2,"unit":"piece","note":"en quartiers"},{"id":"oignon-rouge","qty":0.5,"unit":"piece","note":"émincé"},{"id":"paprika","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Marinade : mélangez le jus d’un demi-citron, 2 cuillères d’huile, l’origan, 2 gousses d’ail écrasées, du sel et du poivre. Enrobez-en le porc et laissez mariner 2 h au frais (ou toute une nuit).","Tzatziki : râpez le concombre, salez-le, pressez-le fortement dans un torchon pour retirer son eau. Mélangez-le au yaourt avec la dernière gousse d’ail râpée, l’aneth ciselé, 1 cuillère d’huile et un trait de citron.","Enfilez la viande sur des brochettes. Grillez-les sur un barbecue ou une poêle-gril très chaude 10-12 min en les tournant toutes les 3 min : elles doivent être bien caramélisées sur les arêtes et juteuses à l’intérieur.","Réchauffez les pitas 30 secondes par face sur le gril, badigeonnées d’un peu d’huile.","Garnissez chaque pita de tzatziki, de viande, de tomates et d’oignon, saupoudrez de paprika et arrosez d’un dernier trait de citron."],"tags":["barbecue","riche en protéines","familial","préparation à l’avance","sportif"],"seasons":["printemps","ete"],"technique":"grill","flavors":["grille","acidule","herbace"],"tips":"Le cou de porc (échine) reste moelleux au gril bien mieux que le filet. Le tzatziki se garde 3 jours au frais."},{"id":"med-moussaka-agneau","name":"Moussaka à l’agneau","description":"Couches d’aubergines rôties et de pommes de terre, sauce d’agneau à la cannelle et au vin rouge, épaisse béchamel dorée au fromage : la moussaka des grandes tablées grecques.","emoji":"🍆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":45,"cookTime":100,"difficulty":"intermediaire","servings":6,"ingredients":[{"id":"agneau-hache","qty":800,"unit":"g"},{"id":"aubergine","qty":3,"unit":"piece","note":"en tranches de 1 cm"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"en rondelles de 5 mm"},{"id":"oignon","qty":2,"unit":"piece","note":"hachés"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"vin-rouge","qty":150,"unit":"ml"},{"id":"cannelle","qty":1,"unit":"cac"},{"id":"origan","qty":1,"unit":"cac"},{"id":"huile-olive","qty":6,"unit":"cas"},{"id":"beurre","qty":60,"unit":"g"},{"id":"farine","qty":60,"unit":"g"},{"id":"lait","qty":700,"unit":"ml"},{"id":"oeuf","qty":2,"unit":"piece"},{"id":"parmesan","qty":80,"unit":"g","note":"ou kefalotyri, râpé"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 220 °C. Badigeonnez aubergines et pommes de terre de 5 cuillères d’huile, salez, étalez-les sur deux plaques et rôtissez 25 min jusqu’à ce que les aubergines soient dorées et fondantes.","Sauce : dans une sauteuse, dorez l’agneau 8 min à feu vif dans le reste d’huile en l’émiettant. Ajoutez oignons et ail 5 min, puis le concentré, le vin rouge (2 min de réduction), les tomates, la cannelle et l’origan. Laissez mijoter 25 min à découvert : la sauce doit être épaisse, sans jus.","Béchamel : faites fondre le beurre, ajoutez la farine et cuisez 2 min en fouettant. Versez le lait froid d’un coup et fouettez à feu moyen 6-8 min jusqu’à ce qu’elle nappe épais. Hors du feu, ajoutez la muscade, la moitié du fromage puis les œufs battus.","Montage dans un plat de 30 × 20 cm : pommes de terre au fond, la moitié des aubergines, toute la sauce à l’agneau, le reste des aubergines, puis la béchamel lissée. Parsemez du reste de fromage.","Baissez le four à 180 °C et enfournez 45 min : le dessus doit être gonflé et bien doré.","Laissez reposer au moins 30 min avant de couper : les couches se tiennent et les parts sortent nettes."],"tags":["week-end","four","familial","batch cooking","calorique","réconfortant"],"seasons":["ete","automne"],"technique":"four","flavors":["epice","cremeux","reconfortant"],"tips":"Encore meilleure le lendemain, réchauffée 20 min à 170 °C. Se congèle en parts."},{"id":"med-kleftiko-agneau-feta","name":"Kleftiko : agneau en papillote, pommes de terre et feta","description":"Épaule d’agneau marinée au citron, à l’ail et à l’origan, cuite 4 heures en papillote scellée avec pommes de terre, poivron et feta : la viande se défait à la cuillère.","emoji":"🐑","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":25,"cookTime":240,"restTime":240,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"agneau-epaule","qty":1000,"unit":"g","note":"avec os, en 4 gros morceaux"},{"id":"pomme-de-terre","qty":800,"unit":"g","note":"en gros quartiers"},{"id":"oignon","qty":2,"unit":"piece","note":"en quartiers"},{"id":"ail","qty":8,"unit":"gousse"},{"id":"poivron-rouge","qty":1,"unit":"piece","note":"en lanières"},{"id":"tomate","qty":2,"unit":"piece","note":"en quartiers"},{"id":"feta","qty":120,"unit":"g","note":"en 4 tranches"},{"id":"citron","qty":2,"unit":"piece","note":"jus"},{"id":"origan","qty":2,"unit":"cac"},{"id":"romarin","qty":2,"unit":"brin"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Mélangez le jus des citrons, l’huile, l’ail écrasé, l’origan, 2 cuillères à café de sel et du poivre. Massez-en l’agneau et laissez mariner 4 h au frais (ou une nuit).","Préchauffez le four à 160 °C. Dans un grand plat, posez deux grandes feuilles de papier sulfurisé croisées, puis une couche de papier aluminium en dessous pour solidifier la papillote.","Disposez pommes de terre, oignons, poivron et tomates au fond, salez, posez l’agneau avec sa marinade et le romarin, puis versez le vin blanc.","Refermez le papier en le plissant hermétiquement : la vapeur ne doit pas s’échapper. Enfournez 3 h 30.","Ouvrez la papillote, posez une tranche de feta sur chaque morceau, montez le four à 200 °C et poursuivez 25-30 min à découvert, jusqu’à ce que la viande soit dorée et la feta légèrement gratinée.","Servez directement dans le papier, en arrosant de jus de cuisson : l’agneau doit se détacher de l’os sans couteau."],"tags":["week-end","four","familial","sans gluten","réconfortant","calorique"],"seasons":["printemps"],"technique":"four","flavors":["herbace","acidule","reconfortant"],"tips":"Le jus de cuisson est un délice sur un pain au levain ; les restes d’agneau effilochés garnissent des pitas."},{"id":"med-kouneli-stifado","name":"Kouneli stifado : lapin aux petits oignons et cannelle","description":"Lapin mijoté avec une montagne d’oignons grelots entiers, vin rouge, vinaigre, cannelle et clous de girofle : une sauce sombre et légèrement sucrée, avec des pommes de terre vapeur.","emoji":"🐇","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":30,"cookTime":110,"difficulty":"facile","servings":4,"ingredients":[{"id":"lapin","qty":1300,"unit":"g","note":"1 lapin découpé en 8"},{"id":"echalote","qty":600,"unit":"g","note":"ou oignons grelots, pelés entiers"},{"id":"ail","qty":4,"unit":"gousse"},{"id":"huile-olive","qty":5,"unit":"cas"},{"id":"vin-rouge","qty":250,"unit":"ml"},{"id":"vinaigre-cidre","qty":3,"unit":"cas","note":"vinaigre de vin rouge"},{"id":"tomates-concassees","qty":300,"unit":"g"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"cannelle","qty":1,"unit":"cac","note":"ou 1 bâton"},{"id":"girofle","qty":1,"unit":"pincee","note":"3 clous"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"pomme-de-terre","qty":900,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Plongez les oignons grelots 1 min dans l’eau bouillante : la peau se retire ensuite en pinçant la base. Épongez le lapin et salez-le.","Dans une cocotte, chauffez 3 cuillères d’huile à feu vif et dorez le lapin en deux fournées, 3 min par face. Réservez.","Ajoutez le reste d’huile et les oignons entiers, faites-les dorer 8 min à feu moyen en secouant la cocotte. Ajoutez l’ail et le concentré 1 min.","Déglacez avec le vinaigre puis le vin rouge et laissez bouillonner 2 min. Ajoutez les tomates, la cannelle, le girofle, le laurier et remettez le lapin.","Couvrez et laissez mijoter 1 h 30 à feu très doux, sans remuer pour ne pas écraser les oignons (secouez simplement la cocotte). La sauce doit devenir sirupeuse et les oignons confits ; retirez le couvercle les 15 dernières minutes si elle est trop liquide.","30 min avant la fin, cuisez les pommes de terre épluchées 25 min à la vapeur. Servez le lapin entouré de ses oignons, nappé de sauce, avec les pommes de terre."],"tags":["mijoté","week-end","batch cooking","sans gluten","réconfortant"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["epice","sucre","reconfortant"],"tips":"Le stifado se fait aussi avec du paleron de bœuf (2 h 30 de cuisson). Meilleur le lendemain."},{"id":"med-keftedes-pilafi-tomate","name":"Keftedes à la menthe, pilaf à la tomate et yaourt","description":"Boulettes de bœuf à la menthe et à l’origan, dorées à la poêle, servies sur un riz pilaf tomaté au beurre avec une bonne cuillère de yaourt grec citronné.","emoji":"🧆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":20,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"boeuf-hache","qty":350,"unit":"g"},{"id":"oignon","qty":1,"unit":"piece","note":"râpé, moitié pour les boulettes, moitié pour le riz"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"menthe","qty":10,"unit":"g","note":"ciselée"},{"id":"origan","qty":1,"unit":"cac"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"panure","qty":25,"unit":"g","note":"pain rassis"},{"id":"farine","qty":1,"unit":"cas"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"riz-blanc","qty":120,"unit":"g","note":"long grain, rincé"},{"id":"tomates-concassees","qty":200,"unit":"g"},{"id":"bouillon-volaille","qty":250,"unit":"ml"},{"id":"beurre","qty":10,"unit":"g"},{"id":"yaourt-grec","qty":150,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pilaf : faites fondre le beurre dans une casserole, faites revenir la moitié de l’oignon 3 min, ajoutez le riz et enrobez-le 1 min. Versez tomates et bouillon, salez, portez à ébullition puis couvrez et cuisez 15 min à feu très doux. Laissez reposer 5 min sans ouvrir.","Keftedes : mélangez le bœuf, l’autre moitié d’oignon râpé, l’ail écrasé, la menthe, l’origan, l’œuf, la panure, 1 cuillère à café de sel et du poivre. Pétrissez 1 min jusqu’à ce que la farce soit collante.","Les mains mouillées, formez 12 boulettes légèrement aplaties et roulez-les dans la farine.","Chauffez l’huile dans une grande poêle à feu moyen-vif. Faites dorer les keftedes 8-10 min en les retournant toutes les 2 min : elles doivent être brunes et croustillantes dehors, juste cuites au centre.","Mélangez le yaourt avec le jus du demi-citron et une pincée de sel. Servez les keftedes sur le pilaf avec une cuillère de yaourt."],"tags":["familial","une poêle","riche en protéines","lunch box","économique"],"seasons":[],"technique":"friture-legere","flavors":["herbace","frais","umami"],"tips":"Les keftedes froides se glissent dans une lunch box avec le riz et le yaourt à part."},{"id":"med-dorade-grillee-ladolemono","name":"Dorade grillée ladolemono, horta et pommes de terre","description":"Dorades entières grillées à la peau croustillante, arrosées d’une émulsion huile d’olive-citron-origan, avec des blettes tièdes et des pommes de terre bouillies.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":10,"cookTime":20,"difficulty":"facile","servings":2,"ingredients":[{"id":"bar","qty":2,"unit":"piece","note":"dorades ou bars entiers vidés, écaillés"},{"id":"pomme-de-terre","qty":500,"unit":"g","note":"chair ferme"},{"id":"epinard","qty":200,"unit":"g","note":"blettes ou chicorée sauvage"},{"id":"citron","qty":2,"unit":"piece"},{"id":"huile-olive","qty":5,"unit":"cas"},{"id":"origan","qty":1,"unit":"cac","note":"séché"},{"id":"ail","qty":1,"unit":"gousse","note":"râpée"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les pommes de terre coupées en deux 20 min à l’eau bouillante salée. Ajoutez les blettes en tronçons dans la même eau les 4 dernières minutes, égouttez.","Faites 3 entailles sur chaque face des poissons, séchez-les bien avec du papier absorbant, huilez-les et salez-les généreusement, intérieur compris. Glissez une rondelle de citron dans le ventre.","Grillez-les sur un barbecue bien chaud ou une poêle-gril huilée, 6-7 min par face sans les bouger : la peau doit se détacher seule de la grille. La chair près de l’arête doit être blanche et opaque.","Ladolemono : fouettez 4 cuillères d’huile avec le jus d’un citron, l’origan, l’ail, du sel et du poivre jusqu’à ce que le mélange devienne trouble et légèrement épais.","Servez les poissons avec les pommes de terre et les blettes, le tout généreusement arrosé de ladolemono."],"tags":["rapide","barbecue","léger","sans gluten","riche en protéines"],"seasons":["ete"],"technique":"grill","flavors":["acidule","iode","grille"],"tips":"Au four : 20 min à 220 °C sur une plaque huilée, avec le même résultat ou presque."},{"id":"med-kotopoulo-lemonato-patates","name":"Kotopoulo lemonato : poulet et patates au citron","description":"Cuisses de poulet et quartiers de pommes de terre rôtis ensemble dans un jus citron-moutarde-origan qui confit les patates : tendres dedans, caramélisées sur les bords.","emoji":"🍋","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":15,"cookTime":70,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":4,"unit":"piece"},{"id":"pomme-de-terre","qty":1200,"unit":"g","note":"en quartiers épais"},{"id":"citron","qty":3,"unit":"piece","note":"jus et zeste"},{"id":"ail","qty":6,"unit":"gousse","note":"écrasées"},{"id":"origan","qty":2,"unit":"cac"},{"id":"moutarde","qty":1,"unit":"cas"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"huile-olive","qty":6,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Fouettez jus et zeste de citron, huile, moutarde, ail, origan, 2 cuillères à café de sel et du poivre.","Dans un grand plat à rôtir, mélangez les pommes de terre avec la moitié de la sauce. Posez les cuisses par-dessus, peau vers le haut, et badigeonnez-les du reste.","Versez le bouillon au fond du plat, sans arroser la peau du poulet.","Enfournez 1 h 10. Au bout de 40 min, retournez les pommes de terre dans le jus ; ajoutez un peu d’eau si le fond est sec.","C’est prêt quand la peau est dorée et craquante, que le jus du poulet coule clair près de l’os et que les pommes de terre ont absorbé presque tout le liquide.","Servez directement dans le plat avec le jus restant."],"tags":["four","familial","sans gluten","économique","réconfortant"],"seasons":[],"technique":"roti","flavors":["acidule","herbace"],"tips":"Le secret des patates lemonates : beaucoup de liquide au départ, qu’elles absorbent en cuisant."},{"id":"med-garides-saganaki-orzo","name":"Garides saganaki : crevettes, tomate et feta, orzo","description":"Grosses crevettes mijotées quelques minutes dans une sauce tomate à l’ail et au piment, gratinées de feta fondante, servies sur des pâtes orzo.","emoji":"🦐","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":10,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"crevette","qty":400,"unit":"g","note":"grosses crevettes crues décortiquées"},{"id":"feta","qty":150,"unit":"g"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"pates","qty":160,"unit":"g","note":"orzo / kritharaki"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"oignon-nouveau","qty":3,"unit":"piece","note":"émincés"},{"id":"vin-blanc","qty":50,"unit":"ml","note":"ou un trait d’ouzo"},{"id":"piment-espelette","qty":1,"unit":"pincee"},{"id":"origan","qty":1,"unit":"cac"},{"id":"persil","qty":10,"unit":"g"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le gril du four à 230 °C. Cuisez l’orzo 9-10 min à l’eau bouillante salée, égouttez et arrosez d’un filet d’huile.","Dans une poêle allant au four, faites revenir les oignons nouveaux 2 min dans l’huile, ajoutez l’ail 30 secondes, puis déglacez au vin blanc.","Ajoutez les tomates, l’origan et le piment, laissez mijoter 8 min à feu moyen jusqu’à ce que la sauce épaississe.","Enfoncez les crevettes dans la sauce, émiettez la feta par-dessus et passez 5-6 min sous le gril : les crevettes doivent être roses et la feta fondue et légèrement dorée.","Parsemez de persil et servez sur l’orzo."],"tags":["rapide","four","riche en protéines","sportif","une poêle"],"seasons":["ete"],"technique":"four","flavors":["iode","acidule","piquant"],"tips":"Servez avec du pain pour saucer si vous voulez encore plus de glucides."},{"id":"med-hortopita-poireau-fenouil","name":"Hortopita au poireau, fenouil et feta","description":"Tourte grecque à pâte maison à l’huile d’olive, garnie de poireaux et fenouil fondus, herbes fraîches, feta, ricotta et œufs : croustillante dessus, moelleuse dedans.","emoji":"🥧","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":40,"cookTime":55,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"farine","qty":270,"unit":"g"},{"id":"huile-olive","qty":80,"unit":"ml"},{"id":"eau","qty":130,"unit":"ml","note":"tiède"},{"id":"vinaigre-cidre","qty":1,"unit":"cas"},{"id":"poireau","qty":3,"unit":"piece","note":"émincés"},{"id":"fenouil","qty":1,"unit":"piece","note":"émincé finement"},{"id":"oignon-nouveau","qty":6,"unit":"piece"},{"id":"aneth","qty":20,"unit":"g"},{"id":"menthe","qty":10,"unit":"g"},{"id":"feta","qty":400,"unit":"g"},{"id":"ricotta","qty":250,"unit":"g"},{"id":"oeuf","qty":4,"unit":"piece"},{"id":"sesame","qty":1,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pâte : mélangez la farine, une pincée de sel, 50 ml d’huile, le vinaigre et l’eau tiède. Pétrissez 5 min jusqu’à une pâte lisse et souple, couvrez et laissez reposer 30 min.","Faites fondre poireaux, fenouil et oignons nouveaux dans 2 cuillères d’huile 12 min à feu moyen, jusqu’à ce qu’ils soient tendres et que l’eau soit évaporée. Laissez tiédir.","Mélangez les légumes avec la feta émiettée, la ricotta, 3 œufs, l’aneth et la menthe ciselés et du poivre (pas de sel : la feta suffit).","Préchauffez le four à 190 °C. Divisez la pâte en deux, étalez chaque moitié très finement (2 mm) au rouleau. Foncez un plat huilé de 28 cm avec la première, en laissant déborder.","Versez la farce, couvrez de la seconde abaisse, roulez les bords pour souder et piquez le dessus. Badigeonnez du dernier œuf battu avec le reste d’huile et parsemez de sésame.","Enfournez 45-50 min : la tourte doit être dorée et sonner creux quand on tape le dessus. Laissez reposer 15 min avant de découper."],"tags":["four","préparation à l’avance","lunch box","familial","repas froid"],"seasons":["printemps","automne"],"technique":"four","flavors":["herbace","lacte"],"tips":"Délicieuse tiède ou froide : une part dans la lunch box avec une salade de tomates."},{"id":"med-horiatiki-thon-grille","name":"Horiatiki au thon grillé et pain au levain","description":"La vraie salade de village grecque, tomates, concombre, poivron, oignon rouge, olives et bloc de feta à l’origan, avec un steak de thon saisi rosé et du pain grillé.","emoji":"🥗","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":15,"cookTime":5,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"thon","qty":2,"unit":"piece","note":"steaks de 2 cm d’épaisseur"},{"id":"tomate","qty":3,"unit":"piece"},{"id":"concombre","qty":0.5,"unit":"piece"},{"id":"poivron-rouge","qty":0.5,"unit":"piece","note":"vert idéalement"},{"id":"oignon-rouge","qty":0.5,"unit":"piece"},{"id":"olive","qty":60,"unit":"g","note":"Kalamata"},{"id":"feta","qty":150,"unit":"g","note":"en un bloc"},{"id":"pain-levain","qty":4,"unit":"tranche"},{"id":"origan","qty":1,"unit":"cac"},{"id":"huile-olive","qty":4,"unit":"cas"},{"id":"vinaigre-cidre","qty":1,"unit":"cas","note":"vinaigre de vin rouge"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Coupez les tomates en gros quartiers irréguliers, le concombre en demi-rondelles épaisses, le poivron en anneaux fins et l’oignon en lamelles. Salez légèrement et laissez rendre leur jus 5 min.","Huilez légèrement les steaks de thon, salez et poivrez. Saisissez-les 1 min 30 par face dans une poêle très chaude : la tranche doit montrer un cœur rose vif. Laissez reposer 2 min et tranchez.","Grillez les tranches de pain 2 min par face dans la même poêle.","Disposez les légumes et les olives dans deux assiettes, posez la feta en bloc, saupoudrez d’origan, arrosez d’huile et de vinaigre.","Ajoutez le thon tranché à côté et servez avec le pain pour saucer le jus de tomate."],"tags":["rapide","repas froid","riche en protéines","léger","sportif"],"seasons":["ete"],"technique":"poele","flavors":["frais","acidule","iode"],"tips":"Version lunch box : remplacez le thon frais par 160 g de thon à l’huile d’olive égoutté."},{"id":"med-htapodi-salata-pligouri","name":"Salade de poulpe au boulgour, câpres et herbes","description":"Poulpe poché fondant mariné au vinaigre de vin et à l’origan, sur un pligouri (boulgour) aux tomates, concombre, oignon rouge, câpres et persil.","emoji":"🐙","category":"salade-composee","mealTypes":["dejeuner","diner"],"cuisine":"grecque","prepTime":20,"cookTime":60,"restTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"poulpe","qty":1300,"unit":"g","note":"congelé puis décongelé (plus tendre)"},{"id":"boulgour","qty":220,"unit":"g","note":"gros grain"},{"id":"tomate","qty":3,"unit":"piece","note":"en dés"},{"id":"concombre","qty":1,"unit":"piece","note":"en dés"},{"id":"oignon-rouge","qty":1,"unit":"piece","note":"ciselé"},{"id":"capres","qty":2,"unit":"cas"},{"id":"persil","qty":25,"unit":"g","note":"haché"},{"id":"origan","qty":1,"unit":"cac"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"vinaigre-cidre","qty":4,"unit":"cas","note":"vinaigre de vin rouge"},{"id":"huile-olive","qty":8,"unit":"cas"},{"id":"citron","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Mettez le poulpe dans une grande casserole avec le laurier, sans eau, couvrez et chauffez à feu moyen : il rend son eau en 10 min. Ajoutez alors de l’eau à hauteur et laissez frémir 45-50 min à feu doux. Il est cuit quand la pointe d’un couteau s’enfonce dans l’épaisseur du tentacule comme dans du beurre.","Laissez-le refroidir 15 min dans son eau, puis coupez les tentacules en tronçons de 2 cm.","Marinez le poulpe tiède avec 3 cuillères de vinaigre, 4 cuillères d’huile, l’origan et du poivre, au moins 2 h au frais.","Versez le boulgour dans une casserole avec 450 ml d’eau bouillante salée, couvrez et cuisez 12 min à feu doux, puis laissez gonfler 10 min hors du feu. Égrainez à la fourchette et laissez refroidir.","Mélangez le boulgour avec tomates, concombre, oignon, câpres, persil, le jus du citron, le reste de l’huile et du vinaigre.","Servez le boulgour surmonté du poulpe mariné et de sa marinade."],"tags":["repas froid","préparation à l’avance","lunch box","riche en protéines","léger"],"seasons":["ete"],"technique":"bouilli","flavors":["iode","acidule","frais"],"tips":"Le poulpe mariné se garde 4 jours au frais dans sa marinade : préparez-le le dimanche pour les lunch box."}]`);export{e as default};